import { useCallback, useEffect, useState } from "react"
import { setLight, setRoomLights, updateRoom, setRoomTarget, createSchedule, updateSchedule, deleteSchedule, cleanRooms, calibrateTrv, switchPlug, fetchPlugSchedules, addPlugSchedule, deletePlugSchedule } from "../api"
import Hint from "../../common/Hint"
import { Pill } from "../../common/ui"
import Collapsible from "../../common/Collapsible"
import { readLayout, orderedSections, orderedTiles } from "../layout"
import "./room.css"

const WEEKDAYS = [["1", "Mo"], ["2", "Di"], ["3", "Mi"], ["4", "Do"], ["5", "Fr"], ["6", "Sa"], ["7", "So"]]

function fmtTemp(value) {
    if (value === null || value === undefined || value === "") return "–"
    return `${Number(value).toFixed(1).replace(".", ",")} °C`
}

function weekdayLabel(weekdays) {
    if (weekdays === "1234567") return "täglich"
    if (weekdays === "12345") return "Mo–Fr"
    if (weekdays === "67") return "Sa + So"
    return WEEKDAYS.filter(([d]) => weekdays.includes(d)).map(([, l]) => l).join(", ")
}

/* A section of the panel: the shared Collapsible with the panel's own frame.
   Its id is also the key its open state is remembered under, so folding the
   heating plan away stays folded on the next room as well - which is the point,
   the decision is about the kind of block, not about one room. */
function Section({ id, title, chips, summary, startOpen, children }) {
    return (
        <Collapsible id={id} store="home.room.open." className="as-section"
                     title={<h5 className="home-h4">{title}</h5>}
                     chips={chips} summary={summary} defaultOpen={startOpen}>
            {children}
        </Collapsible>
    )
}

export default function RoomPanel({ room, hue, shelly, vacuum, energy, layout: rawLayout, onChanged }) {
    const [error, setError] = useState("")
    /* For actions whose result is not visible in the next refresh. Calibrating
       a valve takes about a minute and the symptom only clears afterwards, so
       without a word here the button looks like it did nothing. */
    const [note, setNote] = useState("")

    if (!room) {
        return (
            <div className="ui-card">
                <p className="ui-empty">Einen Raum im Grundriss antippen.</p>
            </div>
        )
    }

    async function run(action, said) {
        try {
            await action()
            setError("")
            setNote(said || "")
            onChanged()
        } catch (e) {
            setError(e.message)
            setNote("")
        }
    }

    const layout = readLayout(rawLayout)
    const sections = orderedSections(layout, { room, hue, shelly, vacuum, energy })
    /* Counted from the same builder the list below uses, so the heading and
       the block can never disagree about how many faults there are. */
    const problems = noticesOf({
        climate: room.climate || {},
        shelly,
        suspect: ((shelly || {}).valve_watch || []).filter(v =>
            v.symptom && ((room.climate || {}).items || []).some(t => String(t.id) === v.trv_id)),
        drifted: (room.climate || {}).trv_target != null && room.target_temp != null
            && Math.abs((room.climate || {}).trv_target - room.target_temp) >= 0.5,
        room,
        run,
    }).length

    return (
        <div className="ui-card room-panel">
            <div className="home-card-header">
                <h4>{room.name}</h4>
                <span className="home-meta home-num">{room.area_m2} m²</span>
                {/* How many things are wrong, where somebody looking at the
                    room will see it before scrolling. The list itself is in
                    the climate block; this is the count, so a room can be
                    dismissed at a glance when it is nothing. */}
                {problems > 0 && (
                    <Pill tone="warn" dot className="rp-problem-chip">
                        {problems} {problems === 1 ? "Hinweis" : "Hinweise"}
                    </Pill>
                )}
            </div>

            {/* Order and visibility come from the layout, availability from the
                data. A room with no valve shows no climate block at all rather
                than a block full of dashes. */}
            {sections.map(section => {
                const startOpen = section.openByDefault
                if (section.id === "climate")
                    return <ClimateSection key="climate" room={room} shelly={shelly}
                                           layout={layout} startOpen={startOpen} run={run} />
                if (section.id === "lights")
                    return <LightSection key="lights" room={room} hue={hue} startOpen={startOpen} run={run} />
                if (section.id === "plugs")
                    return <PlugSection key="plugs" room={room} startOpen={startOpen} run={run} />
                if (section.id === "schedule")
                    return <ScheduleSection key="schedule" room={room} shelly={shelly}
                                            startOpen={startOpen} run={run} />
                if (section.id === "vacuum")
                    return <VacuumSection key="vacuum" room={room} vacuum={vacuum}
                                          startOpen={startOpen} run={run} />
                return null
            })}
            {sections.length === 0 && (
                <p className="ui-empty">
                    Für diesen Raum ist noch nichts eingerichtet — unter „Einstellungen“
                    Geräte zuordnen.
                </p>
            )}

            {error && <p className="home-error">{error}</p>}
            {note && <p className="user-hint">{note}</p>}
        </div>
    )
}

/* ── Light ───────────────────────────────────────────────────────────────── */

function LightSection({ room, hue, startOpen, run }) {
    const lights = room.lights || { bound: 0, items: [] }

    if (!hue.configured) {
        return (
            <Section id="lights" title="Licht" startOpen={startOpen}>
                <p className="ui-empty">Hue ist noch nicht eingerichtet — siehe Tab „Einstellungen“.</p>
            </Section>
        )
    }
    if (lights.bound === 0) {
        return (
            <Section id="lights" title="Licht" startOpen={startOpen}>
                <p className="ui-empty">Diesem Raum ist keine Lampe zugeordnet.</p>
            </Section>
        )
    }

    return (
        <Section id="lights" title="Licht" startOpen={startOpen}
                 chips={<span className="home-meta home-num">{lights.on} von {lights.bound} an</span>}
                 summary={`${lights.on} von ${lights.bound} an`}>
            {!hue.reachable && <p className="home-error">Bridge nicht erreichbar — Schalten geht gerade nicht.</p>}

            <div className="home-actions">
                <button className="home-btn primary" disabled={!hue.reachable}
                        onClick={() => run(() => setRoomLights(room.id, { on: true }))}>Alle an</button>
                <button className="home-btn" disabled={!hue.reachable}
                        onClick={() => run(() => setRoomLights(room.id, { on: false }))}>Alle aus</button>
            </div>

            {lights.items.map(light => (
                <LightRow key={light.id} light={light} disabled={!hue.reachable} run={run} />
            ))}
            {lights.known < lights.bound && (
                <p className="ui-empty">
                    {lights.bound - lights.known} zugeordnete Lampe(n) meldet die Bridge nicht mehr.
                </p>
            )}
        </Section>
    )
}

function LightRow({ light, disabled, run }) {
    /* The slider keeps its own value while it is being dragged and only sends on
       release — React fires onChange for every pixel, and the bridge would get a
       burst of writes for a single gesture. */
    const [brightness, setBrightness] = useState(light.brightness ?? 100)

    return (
        <div className="room-light">
            <div className="home-row">
                <span className="home-row-title">{light.name}</span>
                <span className={`home-chip ${light.on ? "home-chip-warn" : ""}`}>{light.on ? "an" : "aus"}</span>
                <button className="home-btn" disabled={disabled}
                        onClick={() => run(() => setLight(light.id, { on: !light.on }))}>
                    {light.on ? "Aus" : "An"}
                </button>
            </div>
            {light.brightness !== null && light.brightness !== undefined && (
                <label className="room-slider-row">
                    <span className="home-meta home-num">{Math.round(brightness)} %</span>
                    <input
                        className="home-slider"
                        type="range" min="1" max="100" step="1"
                        value={brightness}
                        disabled={disabled}
                        aria-label={`Helligkeit ${light.name}`}
                        onChange={e => setBrightness(Number(e.target.value))}
                        onPointerUp={() => run(() => setLight(light.id, { brightness }))}
                        onKeyUp={() => run(() => setLight(light.id, { brightness }))}
                    />
                </label>
            )}
        </div>
    )
}

/* ── Climate ─────────────────────────────────────────────────────────────── */

/* Whether a reading is old is not something this file decides.
 *
 * A BLU device sends when something changes and says nothing in between, so an
 * hour-old value from a still room is the device working as designed. What is
 * remarkable is silence far longer than that room's own habit - and the habit
 * is measured by the service, from the ages it has actually seen. It arrives
 * here as `silent`, judged against `silent_after_s`, so the screen and the
 * notification service cannot disagree about it.
 *
 * It used to be ten minutes flat, and said "check range or battery". Which
 * meant a wall sensor in a quiet bedroom reported a fault every hour, at a
 * hundred per cent battery - and a message that is usually wrong is a message
 * nobody reads when it is right. */

/* What counts as a battery worth mentioning, matching the default of the
   notification rule so the two do not contradict each other on screen. */
const BATTERY_LOW_PCT = 20

function fmtAge(seconds) {
    if (seconds == null) return null
    if (seconds < 90) return "gerade"
    const minutes = Math.round(seconds / 60)
    return minutes < 60 ? `vor ${minutes} min` : `vor ${Math.round(minutes / 60)} h`
}

function fmtSpan(seconds) {
    if (seconds == null) return null
    if (seconds < 90) return `${Math.round(seconds)} s`
    const minutes = Math.round(seconds / 60)
    return minutes < 60 ? `${minutes} min` : `${Math.round(minutes / 60)} h`
}

/* One tile each, keyed by the ids in layout.js. Only the ones with a value
   are rendered, and in the order the operator put them in. */
function climateTile(id, climate) {
    switch (id) {
        case "temperature":
            return {
                label: "Temperatur",
                value: fmtTemp(climate.temperature),
                hint: fmtAge(climate.age_s),
                /* Only where it is unremarkable: when the reading really is
                   too old there is a line below saying so, and two
                   explanations of the same number contradict each other. */
                tip: climate.age_s > 300 && !climate.silent
                    ? "Der Fühler sendet, wenn sich etwas ändert, nicht im Takt. "
                      + "In einem ruhigen Raum ist der letzte Messwert deshalb normal alt."
                    : null,
                note: climate.temperature_source === "sensor" ? "Wandfühler" : "Ventilkopf",
            }
        case "humidity":
            return { label: "Luftfeuchte", value: `${climate.humidity} %` }
        case "trv_target":
            return { label: "Ventil-Soll", value: fmtTemp(climate.trv_target) }
        case "valve":
            return { label: "Ventilstellung", value: `${climate.valve_position} %` }
        case "head":
            return { label: "Kopftemperatur", value: fmtTemp(climate.head_temperature),
                     note: "im Ventil" }
        case "battery":
            return { label: "Batterie", value: `${climate.battery} %` }
        case "window":
            return { label: "Fenster", value: climate.window_open ? "offen" : "zu" }
        default:
            return null
    }
}

function ClimateSection({ room, shelly, layout, startOpen, run }) {
    const [target, setTarget] = useState(room.target_temp ?? "")
    const climate = room.climate || {}
    const scheduled = room.scheduled
    const tiles = orderedTiles(layout, climate)
    const weakBattery = climate.battery != null && climate.battery <= BATTERY_LOW_PCT
    /* What the service suspects of this room's valves. Matched by id rather
       than by room, because a room can carry two radiators and only one of
       them loses its calibration. */
    const suspect = ((shelly || {}).valve_watch || [])
        .filter(v => v.symptom && (climate.items || []).some(t => String(t.id) === v.trv_id))

    /* The setpoint on the valve and the wish on the room are two values, and
       they drift apart: somebody turns the knob on the radiator, or a valve was
       out of reach when the last change went out. Saying so is the whole point
       - otherwise the panel shows a number that is not what is heating. */
    const drifted = climate.trv_target != null && room.target_temp != null
        && Math.abs(climate.trv_target - room.target_temp) >= 0.5

    return (
        <Section id="climate" title="Klima" startOpen={startOpen}
                 summary={[climate.temperature != null && fmtTemp(climate.temperature),
                           climate.humidity != null && `${climate.humidity} %`]
                          .filter(Boolean).join(" · ")}
                 chips={climate.temperature_source === "sensor" && climate.head_temperature != null && (
                    <Hint>
                        Die Temperatur kommt vom Wandfühler. Der Fühler im Ventilkopf sitzt in
                        der Fensternische auf einem meist kalten Heizkörper und liest
                        systematisch zu niedrig — hier gerade
                        {" "}{fmtTemp(climate.head_temperature)}.
                    </Hint>
                 )}>
            <div className="room-readings">
                {tiles.map(tile => {
                    const data = climateTile(tile.id, climate)
                    return data && <Reading key={tile.id} {...data} />
                })}
            </div>

            {climate.bound === 0 && (
                <p className="ui-empty">
                    {shelly && !shelly.configured
                        ? "Kein BLU-Gateway eingerichtet — unter „Einstellungen“ verbinden."
                        : "Kein Gerät in diesem Raum — unter „Einstellungen“ zuordnen."}
                </p>
            )}
            {climate.bound > 0 && !climate.available && (
                <p className="ui-empty">
                    {shelly && shelly.error
                        ? `Gateway meldet: ${shelly.error}`
                        : "Noch kein Messwert gemeldet."}
                </p>
            )}
            {/* Every fault this room has, as one list rather than as four
                stacked red paragraphs. A room with two small problems used to
                fill half the panel with warnings and read like an emergency;
                now the first one is shown and the rest are a count away. */}
            <Notices items={noticesOf({ climate, shelly, suspect, drifted, room, run })} />

            <div className="home-form">
                <label className="home-field room-target">
                    <span className="room-field-label">
                        Soll-Temperatur
                        {climate.bound > 0 && (
                            <Hint>
                                Setzen baut eine Bluetooth-Verbindung zum Ventil auf und dauert
                                ein paar Sekunden. Gelesen wird dagegen aus dem Zwischenspeicher
                                des Gateways, das kostet keine Batterie.
                            </Hint>
                        )}
                    </span>
                    <input type="number" min="4" max="30" step="0.5" inputMode="decimal"
                           value={target} onChange={e => setTarget(e.target.value)} />
                </label>
                <div className="home-form-actions">
                    {/* Not disabled on an unchanged value when the valve disagrees: resending
                        the same wish is exactly what one wants after a valve missed it. */}
                    <button className="home-btn primary"
                            disabled={!drifted && String(target) === String(room.target_temp ?? "")}
                            onClick={() => run(async () => {
                                if (target === "") return updateRoom(room.id, { target_temp: null })
                                const result = await setRoomTarget(room.id, Number(target))
                                const failed = (result.valves || []).filter(v => !v.ok)
                                if (failed.length) {
                                    throw new Error(`Ventil ${failed.map(v => v.id).join(", ")}: ${failed[0].error}`)
                                }
                            })}>Übernehmen</button>
                </div>
            </div>
            {scheduled && (
                <p className="ui-empty">
                    Laut Heizplan gerade {fmtTemp(scheduled.target_temp)} (seit {scheduled.since}
                    {scheduled.days_back > 0 ? " am Vortag" : ""}).
                </p>
            )}
        </Section>
    )
}

function Reading({ label, value, hint, note, tip }) {
    return (
        <div className="room-reading">
            <span className="home-meta">
                {label}
                {tip && <Hint>{tip}</Hint>}
            </span>
            <span className="room-reading-value">{value}</span>
            {(hint || note) && (
                <span className="home-meta room-reading-hint">
                    {[note, hint].filter(Boolean).join(" · ")}
                </span>
            )}
        </div>
    )
}

/* ── What is wrong with this room ─────────────────────────────────────────── */

/* Every fault, built once, so the count in the room's heading and the list in
   its climate block can never disagree about how many there are.
 *
 * Each entry carries its own text and, where there is something to do about
 * it, the control that does it. Returned in the order they matter: a device
 * that has stopped reporting first, because every other reading in the panel
 * is suspect while it is true. */
function noticesOf({ climate, shelly, suspect, drifted, room, run }) {
    const items = []

    if (climate.bound > 0 && climate.available && shelly && shelly.error) {
        items.push({
            key: "gateway",
            body: <>
                Gateway meldet: {shelly.error}. Angezeigt wird der letzte
                Stand{shelly.snapshot_age_s != null
                    ? ` von vor ${fmtSpan(shelly.snapshot_age_s)}`
                    : ""}.
            </>,
        })
    }

    /* A flat battery and a device out of range need different things done
       about them, and a device can be silent with a full battery - which is
       what one combined message used to get wrong. */
    if (climate.silent) {
        items.push({
            key: "silent",
            body: <>
                Seit {fmtAge(climate.age_s)} kein Messwert
                {climate.quiet_s != null
                    ? ` — sonst meldet sich der Raum spätestens alle ${fmtSpan(climate.quiet_s)}.`
                    : "."}
                {" "}Gerät außer Reichweite oder stromlos.
            </>,
        })
    }

    /* A valve knows where its stem is only because it once drove to both ends
       and remembered. When that memory goes, the position it reports stops
       describing reality, and nothing announces it. */
    for (const valve of suspect) {
        items.push({
            key: `valve-${valve.trv_id}`,
            body: <>
                {valve.detail}
                {valve.last_result ? ` Letzter Kalibrierversuch: ${valve.last_result}.` : ""}
            </>,
            /* Only where it is the remedy. Offering the button for a valve
               that is holding its own setpoint correctly would invite driving
               a motor on a battery to fix a sensor association. */
            action: valve.calibration_helps && (
                <button className="profile-action-btn"
                        onClick={() => run(() => calibrateTrv(valve.trv_id),
                            "Kalibrierung angestoßen — das Ventil fährt einmal ganz "
                            + "auf und zu. Das Ergebnis steht danach im Gerätestatus.")}>
                    Jetzt kalibrieren
                </button>
            ),
        })
    }

    if (climate.battery != null && climate.battery <= BATTERY_LOW_PCT) {
        items.push({
            key: "battery",
            body: `Batterie ${climate.battery} % — wechseln, bevor das Ventil stehen bleibt.`,
        })
    }

    if (drifted) {
        items.push({
            key: "drift",
            body: <>
                Am Ventil stehen {fmtTemp(climate.trv_target)}, gewünscht
                sind {fmtTemp(room.target_temp)}. „Übernehmen“ schickt den Wunsch erneut.
            </>,
        })
    }

    return items
}

/* The first fault, and a count for the rest.
 *
 * All of them at once was the problem: four red paragraphs for four small
 * things, and a room with a quiet sensor and a weak battery looked worse than
 * one with a dead valve. The first is the one to act on; the others are one
 * click away and stay out of the way until then. */
function Notices({ items }) {
    const [open, setOpen] = useState(false)
    if (items.length === 0) return null
    const shown = open ? items : items.slice(0, 1)
    return (
        <div className="rp-notices">
            {shown.map(item => (
                <p key={item.key} className="home-error">
                    {item.body}
                    {item.action && <> {item.action}</>}
                </p>
            ))}
            {items.length > 1 && (
                <button className="profile-action-btn rp-notices-more"
                        onClick={() => setOpen(!open)}>
                    {open ? "weniger" : `${items.length - 1} weitere`}
                </button>
            )}
        </div>
    )
}

/* ── Sockets ─────────────────────────────────────────────────────────────── */

/* Watts as a person reads them: whole numbers, because a socket reporting
   86.4 W is not accurate to a tenth of a watt and the extra digit only makes
   the column jitter. */
function fmtWatt(value) {
    return value == null ? "—" : `${Math.round(value)} W`
}

/* Watt-hours up to a kilowatt-hour, then kilowatt-hours: nobody reads 2480 Wh
   as two and a half kilowatt-hours without doing arithmetic. */
function fmtEnergy(wh) {
    if (wh == null) return null
    if (wh < 1000) return `${Math.round(wh)} Wh`
    return `${(wh / 1000).toFixed(2).replace(".", ",")} kWh`
}

function fmtCountdown(seconds) {
    if (!seconds || seconds <= 0) return null
    const minutes = Math.round(seconds / 60)
    return minutes < 60 ? `${minutes} min` : `${Math.round(minutes / 60)} h`
}

/* The quick countdowns, in minutes. Offered as buttons rather than a number
   field because the common case is "in half an hour" and typing 30 is three
   interactions for one decision. */
const COUNTDOWNS = [15, 30, 60, 120]

function PlugSection({ room, startOpen, run }) {
    const plugs = room.plugs || {}
    const items = plugs.items || []
    const [timerFor, setTimerFor] = useState(null)

    return (
        <Section id="plugs" title="Steckdosen" startOpen={startOpen}
                 summary={[plugs.power_w != null && fmtWatt(plugs.power_w),
                           fmtEnergy(plugs.today_wh)].filter(Boolean).join(" · ")}
                 chips={items.length > 0 && (
                    <Hint>
                        Zeiten und Countdown liegen in der Steckdose selbst, nicht hier —
                        genau wie der Heizplan im Gateway liegt. Eine Dose, die sich um
                        halb zwölf abschaltet, tut das also auch dann, wenn der Pi gerade
                        aus ist. Der Verbrauch kommt aus dem Lebensdauerzähler der Dose;
                        gezeigt wird die Differenz seit Mitternacht, deshalb steht nach
                        einem Werksreset der Dose dort für einen Tag weniger.
                    </Hint>
                 )}>
            {items.length === 0 && (
                <p className="ui-empty">
                    {plugs.bound === 0
                        ? "Keine Steckdose in diesem Raum — unter „Einstellungen“ zuordnen."
                        : "Noch kein Messwert gemeldet."}
                </p>
            )}

            {items.map(plug => (
                <div key={plug.id} className="home-row" data-off={plug.on === false}>
                    <span className="home-row-title">{plug.name}</span>
                    {plug.error
                        ? <span className="home-meta nb-error">{plug.error}</span>
                        : <>
                            <span className="home-meta home-num">{fmtWatt(plug.power_w)}</span>
                            {plug.today_wh != null && (
                                <span className="home-meta">{fmtEnergy(plug.today_wh)} heute</span>
                            )}
                          </>}
                    {fmtCountdown(plug.countdown_s) && (
                        <span className="home-meta rp-countdown">
                            {plug.on ? "aus in " : "an in "}{fmtCountdown(plug.countdown_s)}
                        </span>
                    )}
                    <span className="fps-spacer" />
                    <button className="profile-action-btn"
                            onClick={() => setTimerFor(timerFor === plug.id ? null : plug.id)}>
                        Zeiten
                    </button>
                    <label className="fps-inline">
                        <input type="checkbox" checked={!!plug.on}
                               disabled={plug.on == null}
                               onChange={e => run(() => switchPlug(plug.id, e.target.checked))} />
                        an
                    </label>
                </div>
            ))}

            {timerFor != null && (
                <PlugTimers plug={items.find(p => p.id === timerFor)}
                            run={run} onClose={() => setTimerFor(null)} />
            )}
        </Section>
    )
}

/* A socket's countdown and its weekly times, in one place because they are
   the same question asked twice: once for today, once for every day. */
function PlugTimers({ plug, run, onClose }) {
    const [jobs, setJobs] = useState(null)
    const [error, setError] = useState("")
    const [time, setTime] = useState("22:30")
    const [on, setOn] = useState(false)
    const [days, setDays] = useState([1, 2, 3, 4, 5, 6, 7])

    const load = useCallback(async () => {
        if (!plug) return
        try {
            const answer = await fetchPlugSchedules(plug.id)
            setJobs(answer.jobs || [])
            setError("")
        } catch (e) {
            // A first-generation socket has no weekly timer, and says so. That
            // is an answer, not a failure of this screen.
            setError(e.message)
            setJobs([])
        }
    }, [plug])

    useEffect(() => { load() }, [load])

    if (!plug) return null

    const toggleDay = (id) => setDays(d =>
        d.includes(id) ? d.filter(x => x !== id) : [...d, id].sort())

    return (
        <div className="rp-timers">
            <div className="home-card-header">
                <b>{plug.name}</b>
                <span className="fps-spacer" />
                <button className="profile-action-btn" onClick={onClose}>Schließen</button>
            </div>

            <p className="user-hint">Einmalig, ab jetzt:</p>
            <div className="profile-save-row">
                {COUNTDOWNS.map(minutes => (
                    <button key={minutes} className="profile-action-btn"
                            onClick={() => run(
                                () => switchPlug(plug.id, !!plug.on, minutes * 60),
                                `${plug.name}: ${plug.on ? "aus" : "an"} in ${minutes} min.`)}>
                        {plug.on ? "aus" : "an"} in {minutes} min
                    </button>
                ))}
            </div>

            {error && <p className="home-error">{error}</p>}

            {!error && (
                <>
                    <p className="user-hint">Jede Woche:</p>
                    {jobs && jobs.length === 0 && (
                        <p className="ui-empty">Noch keine feste Zeit.</p>
                    )}
                    {(jobs || []).map(job => (
                        <div key={job.id} className="home-row">
                            <span className="home-row-title home-num">{job.timespec}</span>
                            <span className="home-meta">
                                {job.enable === false ? "inaktiv" : "aktiv"}
                            </span>
                            <span className="fps-spacer" />
                            <button className="profile-action-btn danger"
                                    onClick={() => run(
                                        () => deletePlugSchedule(plug.id, job.id).then(load),
                                        "Zeit entfernt.")}>
                                ✕
                            </button>
                        </div>
                    ))}

                    <div className="rp-timer-form">
                        <label className="home-field">
                            Uhrzeit
                            <input type="time" value={time}
                                   onChange={e => setTime(e.target.value)} />
                        </label>
                        <div className="rp-days">
                            {WEEKDAYS.map(([id, label]) => (
                                <button key={id} type="button"
                                        className="profile-action-btn"
                                        data-on={days.includes(Number(id)) || undefined}
                                        onClick={() => toggleDay(Number(id))}>
                                    {label}
                                </button>
                            ))}
                        </div>
                        <label className="fps-inline">
                            <input type="checkbox" checked={on}
                                   onChange={e => setOn(e.target.checked)} />
                            einschalten (sonst ausschalten)
                        </label>
                        <button className="profile-save-btn" disabled={days.length === 0}
                                onClick={() => run(
                                    () => addPlugSchedule(plug.id, { time, days, on }).then(load),
                                    "Zeit in der Steckdose gespeichert.")}>
                            Hinzufügen
                        </button>
                    </div>
                </>
            )}
        </div>
    )
}

/* ── Heating schedule ────────────────────────────────────────────────────── */

function ScheduleSection({ room, shelly, startOpen, run }) {
    const [adding, setAdding] = useState(false)
    const schedules = room.schedules || []
    const activeId = room.scheduled ? room.scheduled.schedule_id : null
    const bound = (room.climate || {}).bound || 0

    return (
        <Section id="schedule" title="Heizplan" startOpen={startOpen}
                 summary={schedules.length === 0
                     ? "kein Eintrag"
                     : `${schedules.length} Eintrag${schedules.length === 1 ? "" : "e"}`
                       + (room.scheduled ? `, gerade ${fmtTemp(room.scheduled.target_temp)}` : "")}
                 chips={<>
                    {/* The subtitle that used to sit here - "um X Uhr will ich
                        Y Grad" - read as placeholder text left in by accident,
                        and it said what the tooltip beside it says properly. */}
                    <Hint>
                        Die Zeiten liegen als Aufträge im BLU-Gateway, nicht auf dem Pi — sie
                        greifen also auch, wenn der Pi aus ist. Gespiegelt wird bei jeder Änderung.
                    </Hint>
                 </>}>
            {schedules.length === 0 && <p className="ui-empty">Noch kein Eintrag.</p>}
            {/* A plan without a valve goes nowhere - that is a state and stays
                visible. That the plan runs on the gateway is background, and
                background belongs in the tooltip at the heading. */}
            {schedules.length > 0 && bound === 0 && (
                <p className="home-error">
                    Keine Ventile in diesem Raum — der Plan wird nicht ans Gateway geschickt.
                </p>
            )}
            {schedules.map(schedule => (
                <div key={schedule.id} className="home-row">
                    <span className="home-num room-sched-time">{schedule.time}</span>
                    <span className="home-row-title">{fmtTemp(schedule.target_temp)}</span>
                    <span className="home-meta">{weekdayLabel(schedule.weekdays)}</span>
                    {schedule.id === activeId && <span className="home-chip home-chip-accent">aktiv</span>}
                    <button className="home-icon-btn" title={schedule.enabled ? "Pausieren" : "Aktivieren"}
                            onClick={() => run(() => updateSchedule(schedule.id, { enabled: !schedule.enabled }))}>
                        {schedule.enabled ? "⏸" : "▶"}
                    </button>
                    <button className="home-icon-btn delete" title="Löschen"
                            onClick={() => run(() => deleteSchedule(schedule.id))}>✕</button>
                </div>
            ))}

            {adding ? (
                <ScheduleForm
                    onSave={values => run(async () => { await createSchedule(room.id, values); setAdding(false) })}
                    onCancel={() => setAdding(false)} />
            ) : (
                <button className="home-add-btn" onClick={() => setAdding(true)}>+ Zeitpunkt</button>
            )}
        </Section>
    )
}

function ScheduleForm({ onSave, onCancel }) {
    const [time, setTime] = useState("18:00")
    const [temp, setTemp] = useState("21")
    const [days, setDays] = useState(new Set(WEEKDAYS.map(([d]) => d)))

    function toggleDay(day) {
        const next = new Set(days)
        if (next.has(day)) next.delete(day); else next.add(day)
        setDays(next)
    }

    return (
        <div className="home-form">
            <label className="home-field narrow">Uhrzeit
                <input type="time" value={time} onChange={e => setTime(e.target.value)} />
            </label>
            <label className="home-field narrow">Grad
                <input type="number" min="5" max="30" step="0.5" inputMode="decimal"
                       value={temp} onChange={e => setTemp(e.target.value)} />
            </label>
            <div className="home-field wide">Wochentage
                <div className="room-weekdays">
                    {WEEKDAYS.map(([day, label]) => (
                        <button key={day} type="button"
                                className={`home-chip room-day${days.has(day) ? " active" : ""}`}
                                aria-pressed={days.has(day)}
                                onClick={() => toggleDay(day)}>{label}</button>
                    ))}
                </div>
            </div>
            <div className="home-form-actions">
                <button className="home-btn primary" disabled={days.size === 0 || !time}
                        onClick={() => onSave({
                            time,
                            target_temp: Number(temp),
                            weekdays: WEEKDAYS.map(([d]) => d).filter(d => days.has(d)).join(""),
                        })}>Speichern</button>
                <button className="home-btn" onClick={onCancel}>Abbrechen</button>
            </div>
        </div>
    )
}

/* ── Vacuum ──────────────────────────────────────────────────────────────── */

function VacuumSection({ room, vacuum, startOpen, run }) {
    const bound = room.vacuum_rooms || []
    if (bound.length === 0) return null
    return (
        <Section id="vacuum" title="Staubsauger" startOpen={startOpen}>
            <p className="ui-empty">
                Zugeordnet: {bound.map(r => r.name || `#${r.id}`).join(", ")}
            </p>
            <div className="home-actions">
                <button className="home-btn" disabled={!vacuum.connected}
                        onClick={() => run(() => cleanRooms([room.id]))}>
                    Nur diesen Raum saugen
                </button>
            </div>
        </Section>
    )
}
